func:
msg.payload = {
  taskType: 'freeform',
  title: 'Triage a CSV import report',
  tags: ['eval', 'freeform-demo'],
  maxAttempts: 1,
  input: {
    brief: 'Write a support triage note from these observations: a CSV import rejects 12 of 20 rows that contain quoted commas; rows without quoted commas import; no server error is logged. Include a reproduction, a likely cause, and the next diagnostic check. Label any unverified cause as a hypothesis.',
    expectedOutput: 'A concise triage note grounded in the observations.',
    execution: { workspace: 'none' }
  }
};
return msg;

const snapshot = msg.payload;
const targetTaskId = snapshot?.taskId || snapshot?.task?.id || msg.taskId;
const targetAttemptN = snapshot?.acceptedAttemptN;
if (!snapshot?.accepted || !targetTaskId || !Number.isInteger(targetAttemptN)) {
  node.error('Producer has no accepted attempt to judge', msg);
  return null;
}
msg.producerTaskId = targetTaskId;
msg.producerAttemptN = targetAttemptN;
msg.payload = {
  taskType: 'judge_eval_attempt',
  title: 'Judge CSV import triage',
  tags: ['eval', 'freeform-demo', 'judge'],
  correlationId: msg.correlationId,
  maxAttempts: 1,
  input: { targetTaskId, targetAttemptN },
  judgeRubric: {
    rubricId: 'csv-triage',
    version: 'v1',
    scope: 'task-eval',
    preamble: 'Grade the accepted triage note against the supplied observations.',
    criteria: [
      { id: 'evidence', description: 'Accurately reports the observed import pattern without inventing symptoms.', weight: 0.4 },
      { id: 'hypothesis', description: 'Identifies quoted-comma handling as a possible cause and marks it as unverified.', weight: 0.3 },
      { id: 'next-check', description: 'Proposes a concrete check using a minimal quoted-comma row or parser inspection.', weight: 0.3 }
    ]
  }
};
return msg;

const judgment = msg.payload || {};
msg.payload = {
  producerTaskId: msg.producerTaskId,
  producerAttemptN: msg.producerAttemptN,
  judgeTaskId: msg.taskId,
  composite: judgment.composite,
  scores: judgment.scores,
  verdict: judgment.verdict
};
return msg;

const snapshot = msg.payload || {};
msg.payload = {
  status: 'failed',
  taskId: msg.taskId,
  producerTaskId: msg.producerTaskId || null,
  taskStatus: snapshot.status || snapshot.task?.status || null,
  error: snapshot.error || snapshot.attempt?.error || 'No accepted attempt'
};
return msg;
